function decodeUtf8Chunks(chunks, encoding = 'utf8') {
  const decoder = new StringDecoder(encoding);
  let text = '';
  let hadIncomplete = false;
  for (let i = 0; i < chunks.length; i++) {
    const decoded = decoder.write(chunks[i]);
    text += decoded;
    if (i < chunks.length - 1 && decoded.length < chunks[i].length) hadIncomplete = true;
  }
  text += decoder.end();
  return { text, chunksProcessed: chunks.length, hadIncomplete };
