// Write an async function that waits for a specific event on an emitter,
// but with a timeout implemented via AbortSignal.
//
// Returns: { event: string, args: any[], timedOut: boolean }
//
// If the event fires before timeout: { event, args: [...eventArgs], timedOut: false }
// If timeout occurs first: { event, args: [], timedOut: true }
//
// Use events.once() with the { signal } option for cancellation.
// Use AbortController to create the signal and setTimeout to trigger abort.

golden_completion:
async function waitForEvent(emitter, eventName, timeoutMs) {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), timeoutMs);
    try {
        const args = await once(emitter, eventName, { signal: ac.signal });
        clearTimeout(timer);
        return { event: eventName, args, timedOut: false };
    } catch (err) {
        clearTimeout(timer);
        if (err.code === 'ABORT_ERR') {
            return { event: eventName, args: [], timedOut: true };
        }
        throw err;
    }
}

