const assert = require('assert');

// RegExp pattern library using named capture groups
// Each function returns match groups as a structured object

function parseDate(str) {
    const re = /^(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})$/;
    const m = str.match(re);
    if (!m) return null;
    return {
        year: parseInt(m.groups.year, 10),
        month: parseInt(m.groups.month, 10),
        day: parseInt(m.groups.day, 10),
        raw: m[0]
    };
}

const d1 = parseDate('2024-03-15');
assert.strictEqual(d1.year, 2024);
assert.strictEqual(d1.month, 3);
assert.strictEqual(d1.day, 15);
assert.strictEqual(d1.raw, '2024-03-15');

assert.strictEqual(parseDate('not-a-date'), null);

function parseTime(str) {
    const re = /^(?<hours>\d{2}):(?<minutes>\d{2}):(?<seconds>\d{2})$/;
    const m = str.match(re);
    if (!m) return null;
    return {
        hours: parseInt(m.groups.hours, 10),
        minutes: parseInt(m.groups.minutes, 10),
        seconds: parseInt(m.groups.seconds, 10),
        raw: m[0]
    };
}

