function parseUrlQuery(urlStr) {
    const url = new URL(urlStr);
    const params = {};
    url.searchParams.forEach((value, key) => {
        if (params[key]) {
            if (!Array.isArray(params[key])) params[key] = [params[key]];
            params[key].push(value);
        } else {
            params[key] = value;
        }
    });
    return {
        protocol: url.protocol,
        hostname: url.hostname,
