// BaseLogger has a log() method. TimestampLogger has a logWithTime() method.
// Use Reflect.construct to create an object that:
// - Is constructed by BaseLogger (runs BaseLogger constructor)
// - But has TimestampLogger.prototype as its prototype (instanceof TimestampLogger)
// This means the object has BaseLogger's initialized properties but
// TimestampLogger's methods.

function BaseLogger(prefix) {
    this.prefix = prefix;
    this.messages = [];
}
BaseLogger.prototype.log = function(msg) {
    this.messages.push(this.prefix + ': ' + msg);
};

function TimestampLogger(prefix) {
    this.prefix = prefix;
    this.messages = [];
}
TimestampLogger.prototype.logWithTime = function(msg) {
    this.messages.push('[' + new Date().toISOString().slice(0, 10) + '] ' + this.prefix + ': ' + msg);
};

function createHybridLogger(prefix) {

suffix:
}

const assert = require('assert');

const logger = createHybridLogger('APP');

// Has BaseLogger's constructor behavior (prefix and messages initialized)
assert.strictEqual(logger.prefix, 'APP');
assert.deepStrictEqual(logger.messages, []);

// Is instanceof TimestampLogger (not BaseLogger) because new.target is TimestampLogger
assert.strictEqual(logger instanceof TimestampLogger, true);
assert.strictEqual(logger instanceof BaseLogger, false);

// Has TimestampLogger's prototype methods (logWithTime)
assert.strictEqual(typeof logger.logWithTime, 'function');

// Does NOT have BaseLogger's prototype methods (log)
assert.strictEqual(typeof logger.log, 'undefined');

// logWithTime works correctly
logger.logWithTime('started');
assert.strictEqual(logger.messages.length, 1);
assert.ok(logger.messages[0].includes('APP: started'));

