const assert = require('assert');

const ta = new TaggedArray('nums', 1, 2, 3, 4, 5);
assert.strictEqual(ta.length, 5);
assert.strictEqual(ta.tag, 'nums');
assert.strictEqual(ta instanceof TaggedArray, true);
assert.strictEqual(ta instanceof Array, true);

// toTagged format
assert.strictEqual(ta.toTagged(), '[nums]: 1, 2, 3, 4, 5');

// slice returns a PLAIN Array (due to Symbol.species)
const sliced = ta.slice(1, 3);
assert.deepStrictEqual(sliced, [2, 3]);
assert.strictEqual(sliced instanceof Array, true);
assert.strictEqual(sliced instanceof TaggedArray, false);

// map returns a PLAIN Array
const mapped = ta.map(x => x * 10);
assert.deepStrictEqual(mapped, [10, 20, 30, 40, 50]);
assert.strictEqual(mapped instanceof TaggedArray, false);

// filter returns a PLAIN Array
const filtered = ta.filter(x => x > 3);
assert.deepStrictEqual(filtered, [4, 5]);
assert.strictEqual(filtered instanceof TaggedArray, false);

