assert.ok(stack.length >= 2);

// First frame should be innerFunction (getStructuredStack itself is excluded)
assert.strictEqual(stack[0].function, 'innerFunction');
assert.strictEqual(typeof stack[0].file, 'string');
assert.strictEqual(typeof stack[0].line, 'number');

// Second frame should be outerFunction
assert.strictEqual(stack[1].function, 'outerFunction');

