const { performance, PerformanceObserver } = require('perf_hooks');

// Measure the execution time of a synchronous function using Performance marks.
// Must use performance.mark() and performance.measure() (NOT Date.now()).
// Returns { result, durationMs, markStart, markEnd, measureName }
function measureSync(name, fn) {

golden_completion:
const markStart = name + '-start';
const markEnd = name + '-end';
const measureName = name + '-duration';
performance.mark(markStart);
const result = fn();
performance.mark(markEnd);
performance.measure(measureName, markStart, markEnd);
const entry = performance.getEntriesByName(measureName)[0];
return { result, durationMs: entry.duration, markStart, markEnd, measureName };

suffix:
}

const assert = require('assert');

// Measure a simple computation
const r = measureSync('test1', () => {
    let sum = 0;
    for (let i = 0; i < 100000; i++) sum += i;
    return sum;
});

assert.strictEqual(r.result, 4999950000);
assert.strictEqual(typeof r.durationMs, 'number');
assert.ok(r.durationMs >= 0, 'Duration should be non-negative');
assert.strictEqual(r.markStart, 'test1-start');
assert.strictEqual(r.markEnd, 'test1-end');
assert.strictEqual(r.measureName, 'test1-duration');

// Verify marks and measure exist in performance timeline
const marks = performance.getEntriesByType('mark');
assert.ok(marks.some(m => m.name === 'test1-start'));
assert.ok(marks.some(m => m.name === 'test1-end'));

const measures = performance.getEntriesByType('measure');
assert.ok(measures.some(m => m.name === 'test1-duration'));

console.log('Task 50 suffix passed');

